    /**
     * Tests updating a Operator.
     *
     * @return    Operator
     */
    public Operator testUpdate() throws Throwable {
    LOGGER.info( "OperatorTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Operator." );

    StringBuilder msg = new StringBuilder( "Failed to update a Operator : " );
    Operator entity = null;

    try {
        UpdateOperatorCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setOperatorId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Operator." );

        entity = service.updateOperator( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Operator - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

