    /**
     * Tests getting all Operators.
     *
     * @return    Collection
     */
    public List<Operator> testGetAll() throws Throwable {
    LOGGER.info( "OperatorTest:testGetAll() - Retrieving Collection of Operators:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Operator : " );
    List<Operator> collection  = null;

    try {
        // call the static get method on the OperatorService
        collection = service.getAllOperator();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Operator currEntity  = null;
            Iterator<Operator> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getOperatorId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

